{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "ThH, a steroidal compound with very high assay transfer, was reported to have very low oral bioavailability in humans, directly supporting a low-F prediction for the structurally related steroid query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Abiraterone acetate, a high-transfer steroidal drug, has estimated absolute oral bioavailability of <10% in humans in the fasted state, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Testosterone, a high-transfer steroid, has measured absolute oral bioavailability of 3.6 ± 2.5% in humans, demonstrating that the steroid scaffold with polar hydroxyls undergoes extensive first-pass metabolism and poor absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Fulvestrant, a high-transfer steroidal SERD with phenolic and hydroxyl features, has low oral bioavailability in animals and humans, requiring intramuscular administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Mometasone, a high-transfer corticosteroid, has oral bioavailability <1% in humans, further supporting very low oral bioavailability for the steroid-like query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer steroid analogues show low oral bioavailability, mostly below 10%, strongly supporting that the query molecule has F < 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself; prediction relies on high-transfer steroid analogues.",
    "Exact structural identity and formulation-dependent absorption behavior of the query are not directly characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

